import { randomUUID } from "node:crypto";
import { Pool } from "pg";
import { test, expect } from "../helpers/theme-browser";
import { emailHtml } from "../../src/lib/email-html";

const pool = new Pool({ connectionString: process.env.DATABASE_URL });
test.afterAll(() => pool.end());
const longBody = `Hi **{{name}}**,\n\n- **Project one**\n* Project two\n\n1. First step\n2. Second step\n\n${"A paragraph about my work and experience. ".repeat(25)}\n\nhttps://example.test/${"long-path".repeat(90)}\n\n${"Another paragraph.\n\n".repeat(50)}Final paragraph.`;

test("long template and Compose messages scroll independently", async ({
  page,
  themeUser,
}, testInfo) => {
  const contact = randomUUID(),
    template = randomUUID();
  await pool.query(
    `INSERT INTO "Contact" (id,"userId",name,email,company,"jobRole") VALUES ($1,$2,'Alex Smith','[REDACTED_EMAIL]','Acme','Engineer')`,
    [contact, themeUser],
  );
  await pool.query(
    `INSERT INTO "Template" (id,"userId",name,subject,body) VALUES ($1,$2,'Long message','Hello {{name}}',$3)`,
    [template, themeUser, longBody],
  );
  await page.goto(`/templates?edit=${template}`);
  if (testInfo.project.name === "mobile")
    await page.getByRole("tab", { name: "Preview", exact: true }).click();
  // Confirm hydration through a real interaction before filling server-rendered fields.
  await page
    .getByRole("button", { name: "Highlight color", exact: true })
    .click();
  await expect(
    page.getByRole("menu", { name: "Highlight color" }),
  ).toBeVisible();
  await page.keyboard.press("Escape");
  if (testInfo.project.name === "mobile")
    await page.getByRole("tab", { name: "Write", exact: true }).click();
  const editor = page.getByLabel("Message", { exact: true });
  await expect(editor).toHaveCSS("resize", "vertical");
  expect((await editor.boundingBox())!.height).toBeGreaterThanOrEqual(460);
  await editor.fill(longBody + " Updated.");
  await expect(editor).toHaveValue(longBody + " Updated.");
  await editor.evaluate((element: HTMLTextAreaElement) => {
    element.focus();
    element.setSelectionRange(0, 0);
    element.dispatchEvent(new Event("select", { bubbles: true }));
  });
  await page.getByRole("button", { name: "{{company}}", exact: true }).click();
  await expect(editor).toHaveValue("{{company}}" + longBody + " Updated.");
  for (const surface of ["Template", "Personal"]) {
    if (surface === "Personal") {
      page.once("dialog", (dialog) => dialog.accept());
      await page.goto("/compose");
      await page
        .getByLabel("Choose a template", { exact: true })
        .selectOption(template);
      await page.getByRole("checkbox", { name: /Alex Smith/ }).check();
    }
    if (surface === "Template" && testInfo.project.name === "mobile")
      await page.getByRole("tab", { name: "Preview", exact: true }).click();
    const message = page.getByRole("region", {
      name: `${surface} message preview`,
    });
    await expect(message).toContainText("Alex Smith");
    await expect(message.locator("strong mark")).toHaveText("Alex Smith");
    await expect(message.locator("ul li")).toHaveCount(2);
    await expect(message.locator("ol li")).toHaveCount(2);
    const size = await message.evaluate((el) => ({
      height: el.getBoundingClientRect().height,
      scroll: el.scrollHeight,
      client: el.clientHeight,
      width: el.clientWidth,
      scrollWidth: el.scrollWidth,
    }));
    expect(size.height).toBeLessThanOrEqual(
      Math.min(440, page.viewportSize()!.height * 0.55) + 1,
    );
    expect(size.scroll).toBeGreaterThan(size.client);
    expect(size.scrollWidth).toBeLessThanOrEqual(size.width);
    await page.screenshot({
      path: testInfo.outputPath(`${surface.toLowerCase()}-preview.png`),
      fullPage: true,
    });
    await message.focus();
    await expect(message).toBeFocused();
    await page.keyboard.press("Control+End");
    await expect
      .poll(() =>
        message.evaluate(
          (el) => el.scrollTop + el.clientHeight >= el.scrollHeight - 2,
        ),
      )
      .toBe(true);
    await expect(
      page.getByLabel(
        surface === "Template" ? "Preview as" : "Preview recipient",
        { exact: true },
      ),
    ).toBeVisible();
    await expect(page.locator(".mail-preview")).toContainText(
      "Hello Alex Smith",
    );
    expect(
      await page.evaluate(
        () => document.documentElement.scrollWidth <= innerWidth,
      ),
    ).toBe(true);
  }
});

test("delivery HTML wraps naturally at narrow and wide widths", async ({
  page,
}) => {
  for (const width of [320, 1200]) {
    await page.setViewportSize({ width, height: 800 });
    await page.setContent(
      emailHtml(
        `Hi Alex,\n\n${"Experience and projects. ".repeat(100)}\n\nhttps://example.test/${"path".repeat(100)}\n\nFinal paragraph.`,
      ),
    );
    const message = page.locator("body > div");
    expect((await message.boundingBox())!.width).toBeGreaterThan(
      Math.min(640, width - 30) - 1,
    );
    expect(
      await page.evaluate(
        () => document.documentElement.scrollWidth <= innerWidth,
      ),
    ).toBe(true);
    await expect(message).toHaveCSS("text-align", "left");
    await expect(message.locator("br")).toHaveCount(6);
    await expect(message.locator("a")).toHaveCount(1);
  }
});
